const err = (e) => ({ err: e })
const isErr = (v) => typeof v === 'object' && v !== null && 'err' in v

// ---- address helpers
function parseAddr(w) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(w)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const letters = m[1].toUpperCase()
  let col = 0
  for (const ch of letters) col = col * 26 + (ch.charCodeAt(0) - 64)
  // A..Z -> 1..26, AA..ZZ -> 27..702 (AA = 27)
  return { col, row, key: letters + row }
}
function colName(col) {
  return col <= 26 ? String.fromCharCode(64 + col) : String.fromCharCode(64 + Math.floor((col - 1) / 26)) + String.fromCharCode(65 + ((col - 1) % 26))
}
const keyOf = (col, row) => colName(col) + row

// ---- read input
const input = readFileSync(0, 'utf8')
const lines = input.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()
const cells = new Map() // key -> {col,row,content}
for (let i = 0; i < lines.length; i++) {
  const s = lines[i].replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') continue
  const m = /^([^ \t]*)[ \t]*([\s\S]*)$/.exec(s)
  const addrText = m[1]
  const a = parseAddr(addrText)
  if (!a) {
    process.stderr.write(`error: line ${i + 1}: invalid cell address ${addrText}\n`)
    process.exit(2)
  }
  if (cells.has(a.key)) {
    process.stderr.write(`error: line ${i + 1}: cell ${a.key} is declared twice\n`)
    process.exit(2)
  }
  cells.set(a.key, { col: a.col, row: a.row, key: a.key, content: m[2] })
}

// ---- formula parser
function tokenize(src) {
  const toks = []
  let i = 0
  while (i < src.length) {
    const c = src[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(src.slice(i)))) {
      toks.push({ t: 'num', v: Number(m[0]) }); i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(src.slice(i)))) {
      toks.push({ t: 'word', v: m[0] }); i += m[0].length
    } else if ((m = /^(<>|<=|>=|[=<>+\-*\/^(),:])/.exec(src.slice(i)))) {
      toks.push({ t: 'op', v: m[0] }); i += m[0].length
    } else return null
  }
  return toks
}

function parseFormula(src) {
  const toks = tokenize(src)
  if (!toks) return null
  let p = 0
  const peek = () => toks[p]
  const isOp = (v) => toks[p] && toks[p].t === 'op' && toks[p].v === v
  const fail = () => { throw new Error('syntax') }
  function cmp() {
    let l = add()
    while (peek() && peek().t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(peek().v)) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) { const op = toks[p++].v; l = { k: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) { const op = toks[p++].v; l = { k: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { k: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) { const op = toks[p++].v; return { k: 'un', op, e: unary() } }
    return primary()
  }
  function arg() {
    // range directly as an argument
    if (peek() && peek().t === 'word' && toks[p + 1] && toks[p + 1].t === 'op' && toks[p + 1].v === ':') {
      const a = toks[p].v
      p += 2
      if (!peek() || peek().t !== 'word') fail()
      const b = toks[p++].v
      return { k: 'range', a, b }
    }
    return cmp()
  }
  function primary() {
    const t = peek()
    if (!t) fail()
    if (t.t === 'num') { p++; return { k: 'num', v: t.v } }
    if (t.t === 'op' && t.v === '(') {
      p++
      const e = cmp()
      if (!isOp(')')) fail()
      p++
      return e
    }
    if (t.t === 'word') {
      p++
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) { p++; return { k: 'call', name: t.v.toUpperCase(), args } }
        for (;;) {
          args.push(arg())
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          fail()
        }
        return { k: 'call', name: t.v.toUpperCase(), args }
      }
      if (isOp(':')) {
        // range outside a function argument: grammar accepts, evaluates to #ERR!
        p++
        if (!peek() || peek().t !== 'word') fail()
        const b = toks[p++].v
        return { k: 'range', a: t.v, b, misplaced: true }
      }
      const u = t.v.toUpperCase()
      if (u === 'TRUE') return { k: 'bool', v: true }
      if (u === 'FALSE') return { k: 'bool', v: false }
      return { k: 'ref', w: t.v }
    }
    fail()
  }
  try {
    const e = cmp()
    if (p !== toks.length) return null
    return e
  } catch {
    return null
  }
}

// a misplaced range: mark any range not directly an argument
function markMisplaced(node, direct) {
  if (!node) return
  if (node.k === 'range') { if (!direct) node.misplaced = true; return }
  if (node.k === 'bin') { markMisplaced(node.l, false); markMisplaced(node.r, false) }
  else if (node.k === 'un') markMisplaced(node.e, false)
  else if (node.k === 'call') node.args.forEach((a) => markMisplaced(a, true))
}

function rangeCells(n) {
  const a = parseAddr(n.a), b = parseAddr(n.b)
  if (!a || !b) return null
  const out = []
  for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
    for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) out.push(keyOf(c, r))
  return out
}

// ---- parse every cell
for (const c of cells.values()) {
  if (c.content[0] === '=') {
    const ast = parseFormula(c.content.slice(1))
    if (ast) markMisplaced(ast, false)
    c.ast = ast
    c.formula = true
  }
}

// ---- evaluation
const memo = new Map()
const active = new Set()

function cellValue(key) {
  if (memo.has(key)) return memo.get(key)
  const c = cells.get(key)
  if (!c) return 0
  if (active.has(key)) return err('#CYCLE!')
  active.add(key)
  let v
  if (c.formula) v = c.ast ? evalNode(c.ast) : err('#ERR!')
  else v = literal(c.content)
  active.delete(key)
  memo.set(key, v)
  return v
}

function literal(s) {
  if (s === '') return 0
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(s)) return Number(s)
  if (ERRS.has(s)) return err(s)
  return s
}

const toNum = (v) => (typeof v === 'number' ? v : typeof v === 'boolean' ? (v ? 1 : 0) : err('#VALUE!'))
const fin = (n) => (Number.isFinite(n) ? n : err('#DIV/0!'))
const rank = (v) => (typeof v === 'number' ? 0 : typeof v === 'string' ? 1 : 2)

function evalNode(n) {
  switch (n.k) {
    case 'num': return n.v
    case 'bool': return n.v
    case 'ref': {
      const a = parseAddr(n.w)
      return a ? cellValue(a.key) : err('#REF!')
    }
    case 'range': return err('#ERR!')
    case 'un': {
      const v = evalNode(n.e)
      if (isErr(v)) return v
      const x = toNum(v)
      if (isErr(x)) return x
      return n.op === '-' ? fin(-x) : x
    }
    case 'bin': {
      const l = evalNode(n.l)
      const r = evalNode(n.r)
      if (isErr(l)) return l
      if (isErr(r)) return r
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        let d
        if (rank(l) !== rank(r)) d = rank(l) - rank(r)
        else if (typeof l === 'string') d = l === r ? 0 : [...l].map((c) => c.codePointAt(0)).reduce((acc, x, i, arr) => acc, 0) || cmpPoints(l, r)
        else d = l < r ? -1 : l > r ? 1 : 0
        switch (n.op) {
          case '=': return d === 0
          case '<>': return d !== 0
          case '<': return d < 0
          case '<=': return d <= 0
          case '>': return d > 0
          default: return d >= 0
        }
      }
      const a = toNum(l)
      if (isErr(a)) return a
      const b = toNum(r)
      if (isErr(b)) return b
      switch (n.op) {
        case '+': return fin(a + b)
        case '-': return fin(a - b)
        case '*': return fin(a * b)
        case '/': return b === 0 ? err('#DIV/0!') : fin(a / b)
        default: return fin(Math.pow(a, b))
      }
    }
    case 'call': return evalCall(n)
  }
}

function cmpPoints(a, b) {
  const x = [...a], y = [...b]
  for (let i = 0; i < Math.min(x.length, y.length); i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d < 0 ? -1 : 1
  }
  return x.length === y.length ? 0 : x.length < y.length ? -1 : 1
}

// values contributed by one argument (list), or an error
function argValues(a) {
  if (a.k === 'range') {
    const ks = rangeCells(a)
    if (!ks) return [err('#REF!')]
    return ks.map(cellValue)
  }
  return [evalNode(a)]
}

function evalCall(n) {
  const N = n.args.length
  const name = n.name
  const known = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF']
  if (!known.includes(name)) return err('#NAME?')
  if (name === 'IF' ? N !== 3 : name === 'ABS' ? N !== 1 : N < 1) return err('#ERR!')
  if (name === 'IF') {
    let c
    if (n.args[0].k === 'range') {
      const vs = argValues(n.args[0])
      if (vs.length !== 1) return err('#ERR!')
      c = vs[0]
    } else c = evalNode(n.args[0])
    if (isErr(c)) return c
    let t
    if (typeof c === 'boolean') t = c
    else if (typeof c === 'number') t = c !== 0
    else return err('#VALUE!')
    const br = n.args[t ? 1 : 2]
    if (br.k === 'range') {
      const vs = argValues(br)
      return vs.length === 1 ? vs[0] : err('#ERR!')
    }
    return evalNode(br)
  }
  const vals = []
  for (const a of n.args) {
    for (const v of argValues(a)) {
      if (isErr(v)) return v
      vals.push(v)
    }
  }
  if (name === 'COUNT') return vals.filter((v) => typeof v === 'number').length
  if (name === 'ABS' && vals.length !== 1) return err('#ERR!')
  const nums = []
  for (const v of vals) {
    const x = toNum(v)
    if (isErr(x)) return x
    nums.push(x)
  }
  switch (name) {
    case 'ABS': return Math.abs(nums[0])
    case 'SUM': return fin(nums.reduce((s, x) => s + x, 0))
    case 'MIN': return nums.length ? Math.min(...nums) : 0
    case 'MAX': return nums.length ? Math.max(...nums) : 0
    case 'AVG': return nums.length ? fin(nums.reduce((s, x) => s + x, 0) / nums.length) : err('#DIV/0!')
  }
}

// ---- deps
function collect(n, set) {
  if (!n) return
  switch (n.k) {
    case 'ref': { const a = parseAddr(n.w); if (a) set.set(a.key, a); break }
    case 'range': {
      const a = parseAddr(n.a), b = parseAddr(n.b)
      if (a && b) {
        for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
          for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) set.set(keyOf(c, r), { col: c, row: r, key: keyOf(c, r) })
      }
      break
    }
    case 'bin': collect(n.l, set); collect(n.r, set); break
    case 'un': collect(n.e, set); break
    case 'call': n.args.forEach((a) => collect(a, set)); break
  }
}

function fmt(v) {
  if (isErr(v)) return v.err
  if (typeof v === 'boolean') return v ? 'TRUE' : 'FALSE'
  if (typeof v === 'number') return String(Number(v.toPrecision(10)))
  return v
}

const sorted = [...cells.values()].sort((a, b) => a.col - b.col || a.row - b.row)
let out = ''
for (const c of sorted) {
  if (mode === 'values') out += `${c.key}=${fmt(cellValue(c.key))}\n`
  else {
    const set = new Map()
    if (c.formula && c.ast) collect(c.ast, set)
    const ds = [...set.values()].sort((a, b) => a.col - b.col || a.row - b.row)
    out += `${c.key}:${ds.map((d) => ' ' + d.key).join('')}\n`
  }
}
process.stdout.write(out)
